from pathlib import Path
import shutil,re,json,hashlib,subprocess,os,time
R=Path.cwd();B=R/'output/a-to-f-2026-11-08';O=B/'candidate-physical';O.mkdir(exist_ok=True);(O/'inputs').mkdir(exist_ok=True)
OLD=R/'output/btb-ablation-2026-11-08';base=(OLD/'frozen/build.tcl').read_text();core=B/'candidate-generated/SdramPipeline.topEntity/sdram_pipeline_risc.v';assert core.exists()
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
lines=[l for l in base.splitlines() if l.startswith(('set_device','set_option'))];inputs=[]
for filename in re.findall(r'^add_file "([^"]+)"',base,re.M):
 src=Path(filename)
 if src.name=='sdram_pipeline_risc.v':dst=O/'inputs'/src.name;shutil.copyfile(core,dst);role='candidate core'
 elif src.name=='pins.cst':
  dst=O/'pins.cst';dst.write_text('\n'.join(l for l in src.read_text().splitlines() if not l.startswith(('GROUP ','GRP_LOC ','INS_LOC ','// Generated by floorplan_cst.py')))+'\n');role='pin constraints; canonical regions regenerated after synthesis'
 elif src.name=='clocks.sdc':dst=O/'clocks.sdc';shutil.copyfile(OLD/'baseline-p0/clocks.sdc',dst);role='same clocks and report commands as imported controls'
 else:dst=O/'inputs'/src.name;shutil.copyfile(src,dst);assert sha(src)==sha(dst);role='unchanged wrapper or peripheral RTL'
 lines.append(f'add_file "{dst}"');inputs.append({'source':str(core if src.name=='sdram_pipeline_risc.v' else src),'copy':str(dst),'sha256':sha(dst),'role':role})
shutil.copyfile(OLD/'frozen/bootrom-sdram.hex',O/'bootrom-sdram.hex');shutil.copyfile(OLD/'frozen/layout.json',O/'layout.json')
lines+=['run syn','exit'];(O/'synthesis.tcl').write_text('\n'.join(lines)+'\n');(O/'build.tcl').write_text('\n'.join(lines[:-2]+['run all','exit'])+'\n')
(B/'synthesis-inputs.json').write_text(json.dumps({'baseline_netlist_sha256':sha(OLD/'frozen/impl/gwsynthesis/sdram_test.vg'),'rom_sha256':sha(O/'bootrom-sdram.hex'),'inputs':inputs},indent=2)+'\n')
ide=Path('/Applications/GowinIDE.app/Contents/Resources/Gowin_EDA/IDE');env=dict(os.environ,DYLD_LIBRARY_PATH=str(ide/'lib'),DYLD_FRAMEWORK_PATH=str(ide/'lib'))
for attempt in range(5):
 with (O/'synthesis.log').open('w') as log:r=subprocess.run([str(ide/'bin/gw_sh'),'synthesis.tcl'],cwd=O,env=env,stdout=log,stderr=subprocess.STDOUT)
 if r.returncode==0:break
 if 'License verification failed' not in (O/'synthesis.log').read_text():r.check_returncode()
 shutil.copyfile(O/'synthesis.log',O/f'license-{attempt}.log');time.sleep(10)
r.check_returncode()
with (O/'floorplan.log').open('w') as log:subprocess.run(['python3','boards/tangnano20k/sdram/floorplan_cst.py','boards/tangnano20k/sdram/fprisc-81.plan',str(O/'impl/gwsynthesis/sdram_test.vg'),'--layout',str(O/'layout.json'),'-o',str(O/'floorplan.cst')],check=True,stdout=log)
with (O/'pins.cst').open('a') as f:f.write((O/'floorplan.cst').read_text())
with (O/'area.txt').open('w') as f:subprocess.run(['python3','boards/tangnano20k/sdram/area_census.py',str(O/'impl/gwsynthesis/sdram_test.vg'),'--layout',str(O/'layout.json'),'--json',str(O/'area.json')],check=True,stdout=f)
print('Synthesis and canonical floorplan complete')
